head.script:
scwin.svrGubun = js_svrGubun; // DR전환시
scwin.gDepCd = js_dep_cd;
scwin.gLdMktTp = js_market;
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    let str = "null^전체,";
    for (let i = yyyy; i >= 2010; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    // alert(str);
    cmb_ACNTCLS_YY.CBData = str;
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35620.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts1_OnLoadCompleted
 * @description dts1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.dts1_OnLoadCompleted = function(e) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);

        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_Search.setDisabled(false);
        btn_Search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.dts1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts1_OnLoadError
 * @description dts1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts1_OnLoadError = async function(e) {
    try {
        await $c.win.alert(dts1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35620.dts1_OnLoadError" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name dts_DEP_CD_OnLoadCompleted
 * @description dts_DEP_CD 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.dts_DEP_CD_OnLoadCompleted = function(e) {
    try {
        cmb_DEP_CD.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.dts_DEP_CD_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnLoadCompleted
 * @description dts_EMP_NO 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnLoadCompleted = function(e) {
    try {
        cmb_EMP_NO.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.dts_EMP_NO_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function(info) {
    try {
        scwin.gDepCd = cmb_DEP_CD.getValue();
        if (scwin.gDepCd === '') {
            cmb_EMP_NO.setValue('');
        }

        dts_EMP_NO.UseFilter = true;

        dts_EMP_NO.Filter();
        dts_EMP_NO.sort("DEP_CD", 0);
        dts_EMP_NO.sort('', 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        if (scwin.gDepCd === "") {
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "DEP_CD") === scwin.gDepCd || dts_EMP_NO.getCellData(row, "DEP_CD") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
