 */
scwin.btn_Excel_onclick = function(e) {
    try {
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "연평균 시가총액", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
