 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name btn_ISU_CD_onclick
 * @description btn_ISU_CD 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISU_CD_onclick = function(e) {
    try {
        $c.stockSearch.JongmokSearch(txb_ISU_CD, txb_ISU_NM, SECUGRP_ID_ST + ' ' + SECUGRP_ID_RT + ' ' + SECUGRP_ID_DR + ' ' + SECUGRP_ID_FS, js_market, "A");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.btn_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onkeyup
 * @description txb_ISU_CD 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onkeyup = function(e) {
    try {
        if (txb_ISU_CD.value === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스

                Grd_com_isur.Focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.txb_ISU_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onfocus
 * @description txb_ISU_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.txb_ISU_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onblur
 * @description txb_ISU_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISU_CD.value === "") {
            txb_ISU_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.txb_ISU_CD_onblur" });
    }
};

/**
 * @method
 * @name rdo_MKT_ID_onselchange
 * @description rdo_MKT_ID onselchange 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_onselchange = function(info) {
    try {
        scwin.setCtrlByMktId();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35620.rdo_MKT_ID_onselchange" });
    }
};

/**
 * @method
 * @name dts_TR_STATE_CD_OnLoadError
 * @description dts_TR_STATE_CD 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_TR_STATE_CD_OnLoadError = async function(e) {
    try {
        await $c.win.alert(dts_TR_STATE_CD);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35620.dts_TR_STATE_CD_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.fn_GetPar = scwin.getParDetail; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
        scwin.fn_SetPar = undefined;
        await scwin.openDetail();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35620.grd_Grid_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    if (scwin.gLdMktTp === '9') {
        panel_mkt.show("");
        rdo_MKT_ID.setDisabled(!"true");

        $c.cm.setColumnProp(grd_Grid, "TR_MKT_NM", "Show", true);
        rdo_MKT_ID.setValue('1');
        txb_TR_MAGAM_DD.show("");
        lbl_TR_MAGAM_DD.show("");
    } else {
        panel_mkt.hide();
        rdo_MKT_ID.setDisabled(!"false");

        $c.cm.setColumnProp(grd_Grid, "TR_MKT_NM", "Show", false);
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
        txb_TR_MAGAM_DD.hide();
        lbl_TR_MAGAM_DD.hide();
    }
    scwin.setCtrlByMktId();
    let i = rdo_MKT_ID.getValue();
    if (i === 1) {
        scwin.gDepCd = '2600';
    } else if (i === 2) {
        scwin.gDepCd = '3400';
    }
    const sbmOptions = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    cmb_DEP_CD.setValue('');
    cmb_EMP_NO.setValue('');
};

/**
 * @method
 * @name listSync
 * @description 종류주식 주주수요건 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (scwin.svrGubun !== "dr") {
        scwin.setTrstatcd();
        scwin.setTrMagamDd();
    } else {
        txb_TR_MAGAM_DD.setValue($c.ut.cGetToday("yyyymmdd"));
    }
    if (txb_TR_MAGAM_DD.getValue() === "") {
        alert("시장정보 최종 배치일자가 누락입니다. 시스템관리자에게 문의바랍니다.");
        return false;
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_Search.setDisabled(true);
    btn_Search.setBackgroundImage("../img/btn_select_d.gif");
    const acntcls_tp_cd = 'Y'; // 연간
    const acntcls_yy = cmb_ACNTCLS_YY.getValue();
    let acntcls_mm = cmb_ACNTCLS_MM.getValue();
    if (acntcls_mm === "") {
        acntcls_mm = '%';
    }
    let isu_cd = txb_ISU_CD.value;
    if (isu_cd === "") {
        isu_cd = '%';
    }

    let team_cd = cmb_DEP_CD.ValueOfIndex("VALUE", cmb_DEP_CD.getSelectedIndex());
    if (team_cd === "") {
        team_cd = '%';
    }

    let charge_id = cmb_EMP_NO.ValueOfIndex("VALUE", cmb_EMP_NO.getSelectedIndex());
    if (charge_id === "") {
        charge_id = '%';
    }
    let magam_dd = txb_TR_MAGAM_DD.getValue();

    /*
    var url = "/AdminAndDlstedDetection.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01
               + "&method=getTransList&For=AVG_TCP&inputMessageId=AADD_IN&outputMessageId=AADD_OUT_AVG_TCP"
               + "&LD_MKT_TP=" + getObjectValue(rdo_MKT_ID)
               + "&ISU_CD=" + isu_cd + "&TEAM_CD=" + team_cd+ "&CHARGE_ID=" + charge_id+ "&F_SORT=Y&ACNTCLS_YY=" + acntcls_yy+ "&ACNTCLS_MM=" + acntcls_mm;
     */

    const sbmOptions = {
        id : "sbm_dts1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParDetail
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParDetail = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = rdo_MKT_ID.getValue();

    arrPar[1] = dts1.getCellData(dts1.getFocusedRowIndex(), "ISU_CD");

    arrPar[2] = dts1.getCellData(dts1.getFocusedRowIndex(), "ISU_KOR_ABBRV");

    arrPar[3] = dts1.getCellData(dts1.getFocusedRowIndex(), "STRT_DD");

    arrPar[4] = dts1.getCellData(dts1.getFocusedRowIndex(), "END_DD");
    arrPar[5] = txb_TR_MAGAM_DD.getValue();
    return arrPar.length;
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function() {

    const options = {
        id: "ULDSTF35624",
        title: "일별 시가총액 조회",
        type: "browserPopup",
        width: 600 + 5,
        height: 620 + 20,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstmgt/ULDSTF35624.gfm", options);
};

/**
 * @method
 * @name setCtrlByMktId
 * @description set Ctrl By Mkt Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCtrlByMktId = function() {
    let i = rdo_MKT_ID.getValue();
    if (i === '2') {
        lbl_1.hide();
        lbl_1_kosdaq.show("");
    } else {
        lbl_1.show("");
        lbl_1_kosdaq.hide();
    }
};

/**
 * @method
 * @name setTrstatcd
 * @description set Trstatcd 처리
 * @returns {void}
 * @hidden N
 */
scwin.setTrstatcd = function() {
    const stateNm = $c.ud.fn_get_divtrstatcd(dts_TR_STATE_CD, $c.ut.cGetToday("yyyymmdd"), rdo_MKT_ID.getValue());
    let stateCd = "N";
    if (stateNm === "장마감") {
        stateCd = "Y";
    }
    txb_TR_STATE_CD.setValue(stateCd);
};

/**
 * @method
 * @name setTrMagamDd
 * @description set Tr Magam Dd 처리
 * @returns {void}
 * @hidden N
 */
scwin.setTrMagamDd = function() {

    let magam_dd = fn_get_divtrmagamdd(dts_TR_MAGAM_DD, rdo_MKT_ID.getValue());
    txb_TR_MAGAM_DD.setValue(magam_dd);
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    await scwin.setCode();
    scwin.init();
    $c.cm.fn_com_isu(txb_ISU_CD, txb_ISU_NM);
    Grd_com_isur.style.zIndex = 30;
    if (scwin.svrGubun === "dr") {
        alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        txb_TR_STATE_CD.setValue("-");
    } else {
        scwin.setTrstatcd();
    }
    $c.libRoundPanel.PanelToGroupBox(panel_1);
};
